def gen(rng):
    def fmt(cap, ops):
        return f'{len(ops)} {cap}\n' + '\n'.join(ops)
    def rand_op(w):
        k = rng.choices(['push', 'pop', 'top', 'size', 'empty'], weights=w)[0]
        if k == 'push':
            return 'push ' + str(rng.choice([0, -1, 1, rng.randint(-10**9, 10**9), rng.randint(-5, 5)]))
        return k
    tests = [
        fmt(1, ['pop']),
        fmt(1, ['empty', 'top', 'size']),
        fmt(1, ['push 3', 'push 4', 'top', 'pop', 'pop', 'empty']),
        fmt(2, ['push 0', 'push 0', 'push 0', 'size', 'pop', 'pop', 'pop', 'size']),
        fmt(3, ['push 1000000000', 'push -1000000000', 'top', 'size']),
    ]
    for n in (3, 6, 10, 15, 25, 40):
        for _ in range(3):
            cap = rng.randint(1, 5)
            w = rng.choice([[3, 3, 1, 1, 1], [5, 1, 1, 1, 1], [1, 5, 1, 1, 1], [2, 2, 2, 2, 2]])
            tests.append(fmt(cap, [rand_op(w) for _ in range(n)]))
    n = 100000
    tests.append(fmt(100000, ['push ' + str(rng.randint(-10**9, 10**9)) for _ in range(n)]))
    tests.append(fmt(50000, [rand_op([4, 3, 1, 1, 1]) for _ in range(n)]))
    tests.append(fmt(100000, [rand_op([6, 1, 1, 1, 1]) if i < 70000 else rand_op([1, 6, 1, 1, 1]) for i in range(n)]))
    tests.append(fmt(1, [rand_op([1, 1, 1, 1, 1]) for _ in range(n)]))
    return tests
